SELECT sum(value) AS total FROM (
  SELECT value FROM query_result WHERE metric = 'active_users' AND metric_time BETWEEN '2026-07-06' AND '2026-07-12' AND activity__platform = 'web'
) LIMIT 100;

WITH vm AS (SELECT metric_time__day, value FROM "value_moments_week"), au AS (SELECT metric_time__day, value FROM "active_users_week")
SELECT SUM(vm.value) AS total_value_moments, SUM(au.value) AS total_active_users, SUM(vm.value)*1.0/SUM(au.value) AS avg_per_active_user
FROM vm JOIN au USING (metric_time__day);

WITH vm AS (SELECT metric_time__day, value FROM fct_value_moments_week), au AS (SELECT metric_time__day, value FROM fct_active_users_week)
SELECT SUM(vm.value) AS total_value_moments, SUM(au.value) AS total_active_users, SUM(vm.value)*1.0/SUM(au.value) AS avg_per_active_user
FROM vm JOIN au USING (metric_time__day);

WITH vm AS (SELECT metric_time__day, value FROM fct_value_moments WHERE metric_time__day BETWEEN DATE '2026-07-06' AND DATE '2026-07-12'), au AS (SELECT metric_time__day, value FROM fct_active_users WHERE metric_time__day BETWEEN DATE '2026-07-06' AND DATE '2026-07-12')
SELECT SUM(vm.value) AS total_value_moments, SUM(au.value) AS total_active_users, SUM(vm.value)*1.0/SUM(au.value) AS avg_per_active_user
FROM vm JOIN au USING (metric_time__day);

WITH last AS (SELECT SUM(value) AS users FROM (
  VALUES
  (113),(80),(87),(88),(84),(95),(84)
) v(value)), prev AS (SELECT SUM(value) AS users FROM (
  VALUES
  (113),(103),(97),(108),(100),(98),(104)
) v(value)) SELECT last.users AS last_week_users, prev.users AS prev_week_users, last.users - prev.users AS change FROM last, prev;
